-- Wave 5 Nairobi staples — produce, protein, staples, household

on conflict (id) do nothing;

on conflict (merchant_id, location_id, product_id) do nothing;

-- Keep seed freshness current
update public.merchant_prices
set observed_at = now()
where source = 'seed'
  and observed_at < now() - interval '2 days';

update public.fuel_prices
set observed_at = now()
where source = 'seed'
  and observed_at < now() - interval '2 days';
